(* [comment removed for export] *)
Definition CSL : list nat := [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat.
Local Ltac insub := intros ? Hx; rewrite ?in_app_iff in Hx; rewrite ?in_app_iff; tauto.
Local Ltac post_of P := destruct P as (fxpq & Rpq & Mpq & HPpq); exists fxpq, Rpq, Mpq; decompose [and] HPpq; repeat (split; [assumption|]); assumption.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis PO : PESK.sink_policy_ok P.
Let KL := PECKU.klayout_U L LY.
Let SF := PECKU.sfoot_U L LY.

Abbreviation enc_at := (PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4).

(* [comment removed for export] *)
(* [comment removed for export] *)
Theorem v_begin_arr_len_ok :
  PESK.push_back_spec RSEGS CAD EE L HI PMSP.T3 PMSP.T4 P -> PECSU.make_ec_spec L HI -> PMU.opnew_spec L HI -> PMU.opdel_spec L HI ->
  PECSU.put_length_spec L HI P -> PECSU.v_begin_arr_len_spec L HI P.
Proof.
